// Shortens text to a slide field's limit, at a word boundary.
const clip = (value, max) => {
  const s = String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const cut = s.slice(0, max - 1);
  const space = cut.lastIndexOf(' ');
  return (space > max * 0.6 ? cut.slice(0, space) : cut).replace(/[\s,.;:-]+$/, '') + '…';
};
const sentences = (text) => String(text ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').split(/(?<=[.!?])\s+/).map((s) => s.trim()).filter((s) => s.length > 20);

const title = $json.title || 'New on the blog';
const link = $json.link || '';
const text = $json.contentSnippet || $json.content || $json['content:encodedSnippet'] || '';
const points = sentences(text).slice(0, 6);
const slides = [{ template: 'cover', kicker: 'New on the blog', headline: clip(title, 80) }];
for (let i = 0; i + 1 < points.length && slides.length < 4; i += 2) {
  slides.push({ template: 'step', step: slides.length, headline: clip(points[i], 60), body: clip(points[i + 1], 180) });
}
slides.push({ template: 'end_card', cta: 'Read the full post. Link in bio.', handle: clip($json.brand_handle, 28) });
const caption = [title, clip(points.slice(0, 2).join(' '), 300), link ? 'Read it here: ' + link : ''].filter(Boolean).join('\n\n');
return { json: { title, link, caption, slides, idempotency_key: 'n8n-blog-' + (link || title).replace(/[^a-z0-9]+/gi, '-').slice(-120) } };

