// Builds the Postdom post: the rendered slides in order, the caption, a publish time,
// and one target per connected account on the platforms you chose in "Your settings".
const settings = $('Your settings').item.json;
const slides = $('Slides ready?').item.json;
const copy = $('Write slide copy').item.json;
const wanted = String(settings.platforms).split(',').map((p) => p.trim().toLowerCase()).filter(Boolean);
const accounts = ($json.accounts || []).filter((a) => a.status === 'connected' && wanted.includes(a.platform));
if (accounts.length === 0) {
  throw new Error('No connected account for: ' + wanted.join(', ') + '. Connect one at https://app.postdom.com, then run again.');
}
const target = (a) => {
  if (a.platform === 'tiktok') {
    return { account_id: a.providerAccountId, platform: 'tiktok', settings: {
      privacy_level: settings.tiktok_privacy, allow_comment: true, allow_duet: false, allow_stitch: false,
      content_preview_confirmed: true, express_consent_given: true, video_made_with_ai: true,
      commercialContentType: 'brand_organic', auto_add_music: true } };
  }
  if (a.platform === 'instagram') return { account_id: a.providerAccountId, platform: 'instagram', settings: { contentType: 'reel', isAiGenerated: true } };
  if (a.platform === 'facebook') return { account_id: a.providerAccountId, platform: 'facebook', settings: { contentType: 'reel' } };
  return { account_id: a.providerAccountId, platform: a.platform, settings: {} };
};
const media = [...slides.media].sort((x, y) => x.position - y.position).map((m) => ({ media_handle: m.media_id }));
const hours = Number(settings.publish_delay_hours) || 0;
const body = {
  caption: copy.caption,
  media,
  targets: accounts.map(target),
  agent_context: { identity: 'n8n blog to slideshow', intent: 'Share a new blog post as a branded slideshow' },
};
if (copy.publish_at) body.publish_at = copy.publish_at;
else if (hours > 0) body.publish_at = new Date(Date.now() + hours * 3600 * 1000).toISOString();
return { json: { body, idempotency_key: copy.idempotency_key + '-post' } };
